//! DataCapability `session.closeSession` (`data-capability.json`): the DM
//! closes the live session in one action. Its microphone stops listening,
//! its close is dated, and a summary of its journal is generated by the
//! summary model of the active provider, then stored on the session with
//! that model's name, for the next preparation to show.
//!
//! The wire payload is empty: the session is the command's target — or,
//! with none, the payload's `session` ([`session_id`]). What is
//! written is the close itself, on the session's partition, `Session/<its
//! id>`; [`prepare`] turns the one into the other:
//!
//! - a live session is closed — `sessionStatus` closed, `closedAt` now,
//!   `microphoneOn` false — and its journal, the transcribed lines with
//!   their time, is the one text sent to the `llm` port, as a
//!   [`TextKind::Journal`] request: never audio (`text-only-no-audio`);
//! - a session in prep or already closed is closed all the same, with no
//!   summary and nothing sent: the DataGuard refuses it under
//!   `status-lifecycle`, and nothing is written;
//! - a provider that cannot be resolved, or that fails, leaves the session
//!   closed without a summary, and says so ([`NO_SUMMARY`]): the microphone
//!   goes off whatever the provider does.
//!
//! The journal lines are never written by a close: the store keeps them as
//! they are, and stops the session's running playbacks (`stop-all`) when
//! it projects the close onto its tables.

use std::collections::BTreeMap;

use ports_llm::{ApiType, Binary, GenerateRequest, Llm, Models, ProviderConfig, Secret, TextKind};
use serde_json::Value;

/// This DataCapability's id, as `data-capability.json` names it.
pub const DATA_CAPABILITY: &str = "session.closeSession";

/// What a close that stores no summary tells the DM, among its warnings.
pub const NO_SUMMARY: &str = "résumé non généré : le fournisseur de résumé n'a pas répondu";

/// The session's fields a close reads and writes, as the Session aggregate
/// declares them.
const STATUS: &str = "sessionStatus";
const TITLE: &str = "sessionTitle";
const CLOSED_AT: &str = "closedAt";
const MICROPHONE: &str = "microphoneOn";
const SUMMARY: &str = "summary";
const SUMMARY_MODEL: &str = "summaryModel";

/// The one status a session is closed from.
const LIVE: &str = "live";

/// One transcribed line of the session's journal: when it was spoken, and
/// what.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Line {
    /// Its time, as the journal shows it.
    pub at: String,
    /// Its text.
    pub text: String,
}

/// What a close becomes before it is submitted.
#[derive(Clone, Debug, PartialEq)]
pub struct Prepared {
    /// The fields written on the session: its status, its close, its
    /// microphone, and — when one was generated — its summary and the
    /// model that wrote it.
    pub payload: BTreeMap<String, Value>,
    /// [`NO_SUMMARY`], when a live session is closed without one.
    pub warning: Option<&'static str>,
}

/// Why a close is not queued.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Refusal {
    /// The target names no session the engine or the tables hold.
    UnknownSession,
}

impl std::fmt::Display for Refusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::UnknownSession => f.write_str("séance inconnue"),
        }
    }
}

/// The session a wire payload names, when it names one — `session`, as
/// the manifest's target `$session` reads it — lowercased, as the tables
/// write a uuid.
#[must_use]
pub fn session_id(wire: &BTreeMap<String, Value>) -> Option<String> {
    wire.get("session")
        .and_then(Value::as_str)
        .map(str::to_lowercase)
}

/// Whether `id` names this DataCapability, with or without its `@version`.
#[must_use]
pub fn names(id: &str) -> bool {
    id.split('@').next() == Some(DATA_CAPABILITY)
}

/// The provider `settings` makes active — the AiSettings row as the tables
/// or the engine hold it: `mode`, `url`, `detectedApiType`, `apiKey`,
/// `binary`, `generationModel`, `summaryModel` — or `None` when it names no
/// provider the port can reach, or no summary model.
#[must_use]
pub fn provider(settings: &BTreeMap<String, Value>) -> Option<ProviderConfig> {
    let models = Models {
        generation: text(settings, "generationModel").to_owned(),
        summary: text(settings, SUMMARY_MODEL).to_owned(),
    };
    if models.summary.trim().is_empty() {
        return None;
    }
    match text(settings, "mode") {
        "api" => {
            let url = text(settings, "url");
            let api_type = match text(settings, "detectedApiType") {
                "cloud" => Some(ApiType::Cloud),
                "opencode" => Some(ApiType::Opencode),
                _ => None,
            };
            let key = Some(text(settings, "apiKey")).filter(|key| !key.is_empty());
            (!url.is_empty()).then(|| ProviderConfig::Api {
                url: url.to_owned(),
                api_type,
                key: key.map(Secret::new),
                models,
            })
        }
        "binaire" | "binary" => {
            let binary = match text(settings, "binary") {
                "claude-code" | "claude" => Some(Binary::ClaudeCode),
                "opencode" => Some(Binary::Opencode),
                _ => None,
            };
            binary.map(|binary| ProviderConfig::Binary { binary, models })
        }
        _ => None,
    }
}

/// The text a summary is asked of: the session's title, then each journal
/// line with its time, in order. Text only: the lines as transcribed.
#[must_use]
pub fn journal_text(session: &BTreeMap<String, Value>, journal: &[Line]) -> String {
    let mut sent = format!("Journal de la séance « {} »", text(session, TITLE));
    if journal.is_empty() {
        sent.push_str("\n(aucune ligne transcrite)");
    }
    for line in journal {
        sent.push('\n');
        sent.push_str(&line.at);
        sent.push(' ');
        sent.push_str(&line.text);
    }
    sent
}

/// Prepares the close of `session` — its row as the commands queued on it
/// will leave it — at `closed_at` (RFC 3339): a live session's `journal` is
/// summarised through `llm` by the summary model `settings` names.
///
/// # Errors
///
/// [`Refusal::UnknownSession`] when `session` holds no status: no session
/// to close.
pub async fn prepare<L: Llm>(
    llm: &L,
    session: &BTreeMap<String, Value>,
    journal: &[Line],
    settings: &BTreeMap<String, Value>,
    closed_at: &str,
) -> Result<Prepared, Refusal> {
    let status = session.get(STATUS).and_then(Value::as_str);
    let Some(status) = status else {
        return Err(Refusal::UnknownSession);
    };
    let mut payload: BTreeMap<String, Value> = [
        (STATUS, Value::from("closed")),
        (CLOSED_AT, closed_at.into()),
        (MICROPHONE, false.into()),
    ]
    .into_iter()
    .map(|(field, value)| (field.to_owned(), value))
    .collect();
    // Not live: the DataGuard refuses it, and nothing reaches the provider.
    if status != LIVE {
        return Ok(Prepared {
            payload,
            warning: None,
        });
    }
    let Some(config) = provider(settings) else {
        return Ok(Prepared {
            payload,
            warning: Some(NO_SUMMARY),
        });
    };
    let request = GenerateRequest::new(TextKind::Journal, journal_text(session, journal));
    let answer = llm
        .generate(&config, &request)
        .await
        .ok()
        .filter(|answer| !answer.text.trim().is_empty());
    let Some(answer) = answer else {
        return Ok(Prepared {
            payload,
            warning: Some(NO_SUMMARY),
        });
    };
    // The model the settings name, as the DM configured it: the one the
    // next preparation shows.
    let model = config.models().summary.clone();
    payload.insert(SUMMARY.to_owned(), answer.text.into());
    payload.insert(SUMMARY_MODEL.to_owned(), model.into());
    Ok(Prepared {
        payload,
        warning: None,
    })
}

/// A field as text; empty when absent, `null` or not a string.
fn text<'a>(row: &'a BTreeMap<String, Value>, field: &str) -> &'a str {
    row.get(field).and_then(Value::as_str).unwrap_or_default()
}
